import json

import requests
from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Data


class CreateTaskTool(Component):
    display_name = 'Create Task'
    description = "File a task now — anything the user asks to track, including soft to-dos ('I should grab X'), which are kind 'list' when undated. Always set domain and kind. Runs immediately. If the item is genuinely uncertain and a wrong guess is expensive, call holdForClarification instead. Copy the returned id into tasks[]."
    icon = 'plus-circle'
    name = 'CreateTaskTool'

    inputs = [
        MessageTextInput(
            name='access_token',
            display_name='Access Token',
            info="Server-injected per run (LangflowInputBinding). Never model-visible.",
            value='',
            tool_mode=False,
        ),
        MessageTextInput(
            name='base_url',
            display_name='Base URL',
            info='Backend origin, e.g. https://api.example.com. Bound to the Langflow global variable STEWARD_API_BASE_URL. Not agent-controllable: letting the model choose a host would be an SSRF hole.',
            value='STEWARD_API_BASE_URL',
            load_from_db=True,
            tool_mode=False,
        ),
        MessageTextInput(
            name='title',
            display_name='Title',
            info="Required. Short title in the user's language, max 240 chars.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='domain',
            display_name='Domain',
            info="Required. One of: health|home|car|finance|family|pets.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='kind',
            display_name='Kind',
            info="Required. 'reminder' fires at a moment and is REJECTED without due_at; 'list' is passive and needs no date. Reminder-shaped but dateless: LOW stakes -> default a sensible due_at and state it; HIGH stakes (bill, flight, court, passport/licence/insurance expiry) -> don't guess, use holdForClarification.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='priority',
            display_name='Priority',
            info="Required. low|normal|high|urgent. 'normal' by default; 'urgent' for hard deadlines and safety/legal/financial cliffs; 'high' on 'asap'; 'low' on 'no rush', even with a date.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='due_at',
            display_name='Due At',
            info="ISO-8601 with T and an explicit offset (2026-08-15T09:00:00+03:00); bare/naive rejected. Omit for a list item.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='tags',
            display_name='Tags',
            info="Optional. Up to 10 lowercase-kebab tags, comma-separated.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='notes',
            display_name='Notes',
            info="Optional. Max 2000 chars, user's language.",
            value='',
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(display_name='Result', name='output', method='createTask'),
    ]

    # ---- shared plumbing -------------------------------------------------

    def _base(self) -> str:
        base = (self.base_url or "").strip().rstrip("/")
        if not base:
            msg = ("base_url is empty. Point this component's Base URL field at the "
                   "Langflow global variable STEWARD_API_BASE_URL.")
            raise ValueError(msg)
        if not base.startswith("http://") and not base.startswith("https://"):
            msg = "base_url must start with http:// or https://"
            raise ValueError(msg)
        return base

    def _headers(self) -> dict:
        token = (self.access_token or "").strip()
        if not token:
            msg = ("access_token is empty. Either tweak this node's Access Token field "
                   "per run, or pass the accessToken value as the tool argument.")
            raise ValueError(msg)
        return {"Content-Type": "application/json", "Authorization": "Bearer " + token}

    def _call(self, method: str, path: str, body=None, params=None) -> dict:
        try:
            url = self._base() + path
            headers = self._headers()
        except ValueError as ex:
            return {"ok": False, "error": "misconfigured", "message": str(ex)}
        try:
            resp = requests.request(
                method, url, json=body, params=params, headers=headers, timeout=30,
            )
        except Exception as ex:  # noqa: BLE001 - surfaced to the agent as a tool result
            return {"ok": False, "error": "network_error", "message": str(ex)}
        if resp.status_code >= 400:
            try:
                payload = resp.json()
            except Exception:  # noqa: BLE001
                payload = {}
            err = payload.get("error", {}) if isinstance(payload, dict) else {}
            return {
                "ok": False,
                "status": resp.status_code,
                "error": err.get("code", "http_error"),
                "message": err.get("message", resp.text[:300]),
                "details": err.get("details"),
            }
        if not resp.content:
            return {"ok": True}
        try:
            parsed = resp.json()
        except Exception:  # noqa: BLE001
            return {"ok": True, "raw": resp.text[:300]}
        out = {"ok": True}
        if isinstance(parsed, dict):
            out.update(parsed)
        else:
            out["data"] = parsed
        return out

    @staticmethod
    def _txt(value):
        """Trimmed string, or None when the model sent nothing."""
        text = (value or "").strip()
        return text or None

    @staticmethod
    def _flag(value):
        """Models send booleans as strings. None means 'not supplied'."""
        text = (value or "").strip().lower()
        if text in ("true", "yes", "1"):
            return True
        if text in ("false", "no", "0"):
            return False
        return None

    @staticmethod
    def _list(value):
        """Comma-separated -> list. None means 'not supplied'."""
        if value is None:
            return None
        text = str(value).strip()
        if not text:
            return None
        return [part.strip() for part in text.split(",") if part.strip()]

    @staticmethod
    def _slim(task):
        """The subset of a task the agent needs back. Keeps tool results small."""
        if not isinstance(task, dict):
            return None
        keys = ("id", "title", "domain", "kind", "status", "priority", "dueAt", "notes", "tags")
        out = {k: task.get(k) for k in keys if task.get(k) is not None}
        subs = task.get("subtasks")
        if isinstance(subs, list) and subs:
            out["subtasks"] = [
                {"id": s.get("id"), "text": s.get("text"), "done": s.get("done")}
                for s in subs
                if isinstance(s, dict)
            ]
        return out

    def _emit(self, result) -> Data:
        return Data(value=json.dumps(result, ensure_ascii=False))

    # ---- tool ------------------------------------------------------------

    def createTask(self) -> Data:
        title = self._txt(self.title)
        domain = self._txt(self.domain)
        if not title:
            return self._emit({"ok": False, "error": "missing_title",
                               "message": "title is required."})
        if domain not in ("health", "home", "car", "finance", "family", "pets"):
            return self._emit({"ok": False, "error": "invalid_domain",
                               "message": "domain must be one of health, home, car, "
                                          "finance, family, pets."})

        kind = self._txt(self.kind)
        due_at = self._txt(self.due_at)
        if kind == "reminder" and not due_at:
            return self._emit({
                "ok": False,
                "error": "reminder_needs_date",
                "message": ("A reminder must have a dueAt. Give it a date, file it as "
                            "kind 'list', or hold it for clarification instead."),
            })

        body = {"title": title, "domain": domain}
        if kind in ("reminder", "list"):
            body["kind"] = kind
        priority = self._txt(self.priority)
        if priority in ("low", "normal", "high", "urgent"):
            body["priority"] = priority
        if due_at:
            body["dueAt"] = due_at
        tags = self._list(self.tags)
        if tags:
            body["tags"] = tags[:20]
        notes = self._txt(self.notes)
        if notes:
            body["notes"] = notes

        result = self._call("POST", "/me/tasks", body=body)
        if not result.get("ok"):
            return self._emit(result)
        return self._emit({"ok": True, "task": self._slim(result.get("task"))})

import json

import requests
from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Data


class UpdateTaskTool(Component):
    display_name = 'Update Task'
    description = "Edit one task: title, domain, priority, status, tags, due date, snooze date, notes. Runs immediately EXCEPT when the new time clashes: nothing is saved and it returns status 'awaiting_confirmation' with 'conflicts'. Resolve that in THIS turn — never stall, never put it in pendingConfirmations. USER named the time -> re-call now with confirm_conflicts='true' and mention the clash. YOU picked it -> re-call at a nearby free time with no flag and say what you chose; if that clashes too, leave the task and say so. 'kind' cannot be sent: the server promotes list to reminder when a confirmed date lands. Literal 'null' clears due_at/notes/snoozed_until/tags."
    icon = 'edit'
    name = 'UpdateTaskTool'

    inputs = [
        MessageTextInput(
            name='access_token',
            display_name='Access Token',
            info="Server-injected per run (LangflowInputBinding). Never model-visible.",
            value='',
            tool_mode=False,
        ),
        MessageTextInput(
            name='base_url',
            display_name='Base URL',
            info='Backend origin, e.g. https://api.example.com. Bound to the Langflow global variable STEWARD_API_BASE_URL. Not agent-controllable: letting the model choose a host would be an SSRF hole.',
            value='STEWARD_API_BASE_URL',
            load_from_db=True,
            tool_mode=False,
        ),
        MessageTextInput(
            name='task_id',
            display_name='Task ID',
            info="Required. Real id from MY TASKS or a tool result; never invented.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='title',
            display_name='Title',
            info="New title, user's language. Omit to keep.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='domain',
            display_name='Domain',
            info="health|home|car|finance|family|pets. Omit to keep.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='priority',
            display_name='Priority',
            info="low|normal|high|urgent. Omit to keep.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='new_status',
            display_name='Status',
            info="open|done|snoozed. Omit to keep.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='due_at',
            display_name='Due At',
            info="ISO-8601 with T and an explicit offset (2026-08-15T09:00:00+03:00); bare/naive rejected. 'null' clears.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='tags',
            display_name='Tags',
            info="FULL REPLACE, not a delta: the final comma-separated lowercase-kebab list. 'null' clears.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='notes',
            display_name='Notes',
            info="Max 2000 chars. 'null' clears.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='confirm_conflicts',
            display_name='Confirm Conflicts',
            info="'true' ONLY on a re-call after a conflict refusal, and only when the user chose that time. Never on a first attempt.",
            value='',
            tool_mode=True,
        ),
        MessageTextInput(
            name='snoozed_until',
            display_name='Snoozed Until',
            info="ISO-8601 with T and an explicit offset (2026-08-15T09:00:00+03:00); bare/naive rejected. 'null' clears.",
            value='',
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(display_name='Result', name='output', method='updateTask'),
    ]

    # ---- shared plumbing -------------------------------------------------

    def _base(self) -> str:
        base = (self.base_url or "").strip().rstrip("/")
        if not base:
            msg = ("base_url is empty. Point this component's Base URL field at the "
                   "Langflow global variable STEWARD_API_BASE_URL.")
            raise ValueError(msg)
        if not base.startswith("http://") and not base.startswith("https://"):
            msg = "base_url must start with http:// or https://"
            raise ValueError(msg)
        return base

    def _headers(self) -> dict:
        token = (self.access_token or "").strip()
        if not token:
            msg = ("access_token is empty. Either tweak this node's Access Token field "
                   "per run, or pass the accessToken value as the tool argument.")
            raise ValueError(msg)
        return {"Content-Type": "application/json", "Authorization": "Bearer " + token}

    def _call(self, method: str, path: str, body=None, params=None) -> dict:
        try:
            url = self._base() + path
            headers = self._headers()
        except ValueError as ex:
            return {"ok": False, "error": "misconfigured", "message": str(ex)}
        try:
            resp = requests.request(
                method, url, json=body, params=params, headers=headers, timeout=30,
            )
        except Exception as ex:  # noqa: BLE001 - surfaced to the agent as a tool result
            return {"ok": False, "error": "network_error", "message": str(ex)}
        if resp.status_code >= 400:
            try:
                payload = resp.json()
            except Exception:  # noqa: BLE001
                payload = {}
            err = payload.get("error", {}) if isinstance(payload, dict) else {}
            return {
                "ok": False,
                "status": resp.status_code,
                "error": err.get("code", "http_error"),
                "message": err.get("message", resp.text[:300]),
                "details": err.get("details"),
            }
        if not resp.content:
            return {"ok": True}
        try:
            parsed = resp.json()
        except Exception:  # noqa: BLE001
            return {"ok": True, "raw": resp.text[:300]}
        out = {"ok": True}
        if isinstance(parsed, dict):
            out.update(parsed)
        else:
            out["data"] = parsed
        return out

    @staticmethod
    def _txt(value):
        """Trimmed string, or None when the model sent nothing."""
        text = (value or "").strip()
        return text or None

    @staticmethod
    def _flag(value):
        """Models send booleans as strings. None means 'not supplied'."""
        text = (value or "").strip().lower()
        if text in ("true", "yes", "1"):
            return True
        if text in ("false", "no", "0"):
            return False
        return None

    @staticmethod
    def _list(value):
        """Comma-separated -> list. None means 'not supplied'."""
        if value is None:
            return None
        text = str(value).strip()
        if not text:
            return None
        return [part.strip() for part in text.split(",") if part.strip()]

    @staticmethod
    def _slim(task):
        """The subset of a task the agent needs back. Keeps tool results small."""
        if not isinstance(task, dict):
            return None
        keys = ("id", "title", "domain", "kind", "status", "priority", "dueAt", "notes", "tags")
        out = {k: task.get(k) for k in keys if task.get(k) is not None}
        subs = task.get("subtasks")
        if isinstance(subs, list) and subs:
            out["subtasks"] = [
                {"id": s.get("id"), "text": s.get("text"), "done": s.get("done")}
                for s in subs
                if isinstance(s, dict)
            ]
        return out

    def _emit(self, result) -> Data:
        return Data(value=json.dumps(result, ensure_ascii=False))

    # ---- tool ------------------------------------------------------------

    def updateTask(self) -> Data:
        task_id = self._txt(self.task_id)
        if not task_id:
            return self._emit({"ok": False, "error": "missing_task_id",
                               "message": "task_id is required."})

        body = {}
        title = self._txt(self.title)
        if title:
            body["title"] = title
        domain = self._txt(self.domain)
        if domain in ("health", "home", "car", "finance", "family", "pets"):
            body["domain"] = domain
        priority = self._txt(self.priority)
        if priority in ("low", "normal", "high", "urgent"):
            body["priority"] = priority
        status = self._txt(self.new_status)
        if status in ("open", "done", "snoozed"):
            body["status"] = status

        # 'null' is how a text-only tool surface expresses "clear this field".
        for field, raw in (("dueAt", self.due_at),
                           ("notes", self.notes),
                           ("snoozedUntil", self.snoozed_until)):
            value = self._txt(raw)
            if value is None:
                continue
            body[field] = None if value.lower() == "null" else value

        tags_raw = self._txt(self.tags)
        if tags_raw is not None:
            body["tags"] = [] if tags_raw.lower() == "null" else (self._list(tags_raw) or [])[:20]

        if not body:
            return self._emit({"ok": False, "error": "nothing_to_update",
                               "message": "No fields supplied. Send at least one change."})

        # Look before writing. A PATCH that moves a matter onto another one used to
        # succeed silently, and the user only discovered the clash later by opening
        # the task and finding a warning over a change nobody had flagged. Surfacing
        # the clash at the write is the difference between a warning and a decision
        # — but the decision resolves inside the same turn, never as a blocked state.
        confirmed = self._flag(self.confirm_conflicts) is True
        moving = "dueAt" in body and body["dueAt"] is not None
        if moving and not confirmed:
            check = self._call(
                "POST",
                "/me/tasks/" + task_id + "/conflicts",
                body={"dueAt": body["dueAt"], "title": body.get("title")},
            )
            # A check that could not run must not become a reason to block the edit;
            # the user asked for this change and the server is still the authority.
            clashes = check.get("conflicts") if check.get("ok") else None
            if clashes:
                return self._emit({
                    "ok": False,
                    "status": "awaiting_confirmation",
                    "error": "conflict_detected",
                    "message": (
                        "NOT SAVED. This time clashes with the matters listed in "
                        "'conflicts'. Resolve this in THIS SAME turn: if the user's "
                        "message explicitly named this time, call updateTask again NOW "
                        "with confirm_conflicts='true' and mention the clash in your "
                        "reply. If you picked the time yourself, re-call with a nearby "
                        "time that avoids the clash instead (no flag). Never end the "
                        "turn stalled on this refusal."
                    ),
                    "conflicts": clashes,
                })

        result = self._call("PATCH", "/me/tasks/" + task_id, body=body)
        if not result.get("ok"):
            return self._emit(result)
        return self._emit({"ok": True, "task": self._slim(result.get("task"))})

